	/**
	 * Resolves the export key of a storage container.
	 *
	 * @param containerId the item container id
	 * @return {@code lootingBag}, {@code seedVault} or {@code groupStorage}, or {@code null} for any other container
	 */
	public static String storageKey(int containerId)
	{
		return STORAGE_KEYS.get(containerId);
	}

	/**
	 * @return the item container ids of every captured storage, in export order
	 */
	public static Iterable<Integer> storageContainerIds()
	{
		return STORAGE_KEYS.keySet();
	}

	/**
	 * Replaces the cached contents of one storage container, dropping empty slots and placeholders.
	 *
	 * @param key       the storage export key, see {@link #storageKey(int)}
	 * @param container the storage item container
	 */
	public void updateStorage(String key, ItemContainer container)
	{
		if (key == null || container == null)
			return;

		List<ItemEntry> items = new ArrayList<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
				items.add(new ItemEntry(item.getId(), getItemName(item.getId()), item.getQuantity()));
		}

		storages.put(key, items);
		storageUpdated.put(key, Instant.now());
	}

	/** Spellbook varbit values 0 to 3, in order; any other value is reported as unknown. */
	private static final String[] SPELLBOOK_NAMES = {"STANDARD", "ANCIENT", "LUNAR", "ARCEUUS"};

	private String spellbook = null;

	/**
	 * Polls the active spellbook from the spellbook varbit (0 standard, 1 ancient, 2 lunar, 3 arceuus).
	 *
	 * @return whether the spellbook changed since the last poll
	 */
	public boolean pollSpellbook()
	{
		int value = client.getVarbitValue(VarbitID.SPELLBOOK);
		String book = value >= 0 && value < SPELLBOOK_NAMES.length ? SPELLBOOK_NAMES[value] : null;
		boolean changed = !Objects.equals(book, spellbook);
		spellbook = book;
		return changed;
	}

	private List<String> unlockedPrayers = null;

	private List<String> quickPrayers = null;

	private String autocastSpell = null;

	private Boolean autocastDefensive = null;

	/**
	 * Polls the unlocked reward prayers, the selected quick prayers and the autocast spell.
	 *
	 * @return whether any of them changed since the last poll
	 */
	public boolean pollPrayerMagic()
	{
		List<String> unlocked = PrayerMagic.unlockedPrayers(client);
		List<String> quick = PrayerMagic.quickPrayers(client);
		String spell = PrayerMagic.autocastSpell(client);
		Boolean defensive = spell != null ? PrayerMagic.autocastDefensive(client) : null;
		boolean changed = !Objects.equals(unlocked, unlockedPrayers) || !Objects.equals(quick, quickPrayers)
			|| !Objects.equals(spell, autocastSpell) || !Objects.equals(defensive, autocastDefensive);
		unlockedPrayers = unlocked;
		quickPrayers = quick;
		autocastSpell = spell;
		autocastDefensive = defensive;
		return changed;
	}

	/** Index of the page title text among the children of the collection log header widget. */
	private static final int CLOG_HEADER_TITLE_INDEX = 0;

	/**
	 * Id of the game's per-item collection log script, which the server runs once for every obtained item
	 * while the log's Search is opened. Arguments, after the script id itself in the event array: item id,
	 * quantity. Taken from WikiSync (script 4100, {@code collection_delayed_transmit}).
	 */
	public static final int CLOG_ITEM_SCRIPT_ID = 4100;

	/** Index of the item id in the argument array of {@link #CLOG_ITEM_SCRIPT_ID}; index 0 is the script id. */
	private static final int CLOG_ITEM_ARG_ID = 1;

	/** Index of the quantity in the argument array of {@link #CLOG_ITEM_SCRIPT_ID}. */
	private static final int CLOG_ITEM_ARG_QUANTITY = 2;

	private final Map<String, CollectionLogPage> clogPages = new LinkedHashMap<>();

	private final Map<Integer, ItemEntry> clogItems = new LinkedHashMap<>();

	private boolean clogSearchActive = false;

	private boolean clogSearchChanged = false;

	private int clogObtained = 0;

	private int clogTotal = 0;

	private Instant clogUpdated = null;

	/**
	 * Captures the collection log page currently drawn. Called when the log's draw-list script has
	 * run, so it only does work as the player opens or switches pages. Each item widget under the
	 * items container is an obtained item when its opacity is 0, and a greyed-out missing item
	 * otherwise. The page is stored under its title, replacing any earlier capture of that page, and
	 * the account-wide counts are read from the collection log varps.
	 *
	 * @return whether the captured data changed
	 */
	public boolean captureCollectionLog()
	{
		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget content = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (header == null || content == null || header.getChildren() == null || content.getChildren() == null)
			return false;

		Widget title = header.getChild(CLOG_HEADER_TITLE_INDEX);
		if (title == null || title.getText() == null || title.getText().isEmpty())
			return false;

		int total = 0;
		List<ItemEntry> obtainedItems = new ArrayList<>();
		for (Widget child : content.getChildren())
		{
			if (child == null || child.getItemId() <= 0)
				continue;

			total++;
			if (child.getOpacity() == 0)
				obtainedItems.add(new ItemEntry(child.getItemId(), getItemName(child.getItemId()),
					Math.max(1, child.getItemQuantity())));
		}

		CollectionLogPage page = new CollectionLogPage(total, obtainedItems.size(), obtainedItems);
		boolean changed = !page.equals(clogPages.get(title.getText()));
		clogPages.put(title.getText(), page);
		for (ItemEntry item : obtainedItems)
			changed |= mergeClogItem(item);

		int obtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int max = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		changed |= obtained != clogObtained || max != clogTotal;
		clogObtained = obtained;
		clogTotal = max;
		if (changed || clogUpdated == null)
			clogUpdated = Instant.now();

		return changed;
	}

	/**
	 * Merges one obtained item into the whole-log item map.
	 *
	 * @param item the obtained item
	 * @return whether the map changed
	 */
	private boolean mergeClogItem(ItemEntry item)
	{
		ItemEntry old = clogItems.get(item.itemId);
		if (old != null && old.quantity == item.quantity)
			return false;

		clogItems.put(item.itemId, item);
		return true;
	}

	/**
	 * Records one obtained item from the game's per-item collection log script, which runs for every
	 * obtained item while the player opens the log's Search. An event with no quantity is ignored rather than
	 * counted as obtained. Only merges into the item map; the pass is
	 * closed by {@link #finishCollectionLogSearch()} so the caller marks the data dirty once per pass.
	 *
	 * @param args the script arguments, including the script id at index 0
	 */
	public void recordCollectionLogItem(Object[] args)
	{
		if (args == null || args.length <= CLOG_ITEM_ARG_QUANTITY
				|| !(args[CLOG_ITEM_ARG_ID] instanceof Integer) || !(args[CLOG_ITEM_ARG_QUANTITY] instanceof Integer))
			return;

		int itemId = (Integer) args[CLOG_ITEM_ARG_ID];
		if (itemId <= 0)
			return;

		int quantity = (Integer) args[CLOG_ITEM_ARG_QUANTITY];
		if (quantity <= 0)
			return;

		clogSearchActive = true;
		clogSearchChanged |= mergeClogItem(new ItemEntry(itemId, getItemName(itemId), quantity));
	}

	/**
	 * Closes a search pass started by {@link #recordCollectionLogItem(Object[])}. Called on a later game
	 * tick, once the script has stopped firing; reads the overall counters and stamps the section.
	 *
	 * @return whether the pass changed the collection log
	 */
	public boolean finishCollectionLogSearch()
	{
		if (!clogSearchActive)
			return false;

		boolean changed = clogSearchChanged;
		clogSearchActive = false;
		clogSearchChanged = false;

		int obtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int max = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		changed |= obtained != clogObtained || max != clogTotal;
		clogObtained = obtained;
		clogTotal = max;
		if (changed || clogUpdated == null)
			clogUpdated = Instant.now();

		return changed;
	}

	/**
	 * Builds the exported collection log. The flat item list holds each obtained item id once, from the
	 * search pass and from every captured page.
	 *
	 * @return the collection log, or {@code null} when nothing has been captured
	 */
	private CollectionLogData buildCollectionLog()
	{
		if (clogPages.isEmpty() && clogItems.isEmpty())
			return null;

		Map<String, CollectionLogPage> pages = new LinkedHashMap<>();
		for (Map.Entry<String, CollectionLogPage> e : clogPages.entrySet())
		{
			CollectionLogPage page = e.getValue();
			pages.put(e.getKey(), new CollectionLogPage(page.total, page.obtained, new ArrayList<>(page.items)));
		}

		return new CollectionLogData(clogObtained, clogTotal, new ArrayList<>(clogItems.values()), pages);
	}

	/** Identity captured by the last snapshot built with a live local player; cleared by {@link #reset()}. */
	private PlayerInfo lastPlayer = null;

	/** Location captured by the last snapshot built with a live local player; cleared by {@link #reset()}. */
	private LocationData lastLocation = null;

	/**
	 * Reads the live player's identity and account context.
	 *
	 * @param localPlayer the local player
	 * @return the player info
	 */
	@SuppressWarnings("deprecation")
	private PlayerInfo readPlayerInfo(Player localPlayer)
	{
		String accountType = null;
		Boolean members = null;
		String book = null;
		if (config.syncAccountInfo())
		{
			AccountType type = client.getAccountType();
			accountType = type != null ? type.name() : null;
			members = client.getWorldType().contains(WorldType.MEMBERS);
			book = spellbook;
		}

		PlayerInfo info = new PlayerInfo(
			localPlayer.getName(),
			localPlayer.getCombatLevel(),
			client.getWorld(),
			accountType,
			members,
			book);
		if (config.syncAccountInfo())
			copyPrayerMagic(unlockedPrayers, quickPrayers, autocastSpell, autocastDefensive, info);

		return info;
	}

	/**
	 * Copies the prayer and magic setup into a player info, copying the lists.
	 *
	 * @param unlocked  unlocked reward prayers, may be {@code null}
	 * @param quick     selected quick prayers, may be {@code null}
	 * @param spell     autocast spell name, may be {@code null}
	 * @param defensive whether the autocast is defensive, may be {@code null}
	 * @param target    the player info to fill
	 */
	private static void copyPrayerMagic(List<String> unlocked, List<String> quick, String spell, Boolean defensive,
		PlayerInfo target)
	{
		target.unlockedPrayers = unlocked != null ? new ArrayList<>(unlocked) : null;
		target.quickPrayers = quick != null ? new ArrayList<>(quick) : null;
		target.autocastSpell = spell;
		target.autocastDefensive = defensive;
	}

	private WorldPoint polledLocation = null;

	private Integer polledEnergy = null;

	/**
	 * Compares the character's real-world location and run energy against the previous call. Meant to
	 * run every game tick so walking or regenerating run energy marks the snapshot dirty.
	 *
	 * @return whether an enabled value (location or vitals) changed since the last call
	 */
	public boolean pollMovement()
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
			return false;

		WorldPoint location = resolveLocation(localPlayer);
		int energy = client.getEnergy() / 100;
		boolean changed = config.syncLocation() && !Objects.equals(location, polledLocation);
		changed |= config.syncVitals() && !Objects.equals(energy, polledEnergy);
		polledLocation = location;
		polledEnergy = energy;
		return changed;
	}

	/**
	 * Resolves the character's real-world point. Inside an instance (raids, boss rooms, player-owned
	 * house) the world location is a copy-area coordinate, so the local point is mapped back to the
	 * template area it was built from.
	 *
	 * @param localPlayer the local player
	 * @return the world point, or {@code null} when it is unavailable
	 */
	private WorldPoint resolveLocation(Player localPlayer)
	{
		LocalPoint local = localPlayer.getLocalLocation();
		WorldPoint mapped = local != null ? WorldPoint.fromLocalInstance(client, local) : null;
		return mapped != null ? mapped : localPlayer.getWorldLocation();
	}

	private Map<String, DailyTask> dailies = null;

	private MiscellaniaData miscellania = null;

	/**
	 * Polls the daily rewards and the Kingdom of Miscellania state.
	 *
	 * @return whether either changed since the last poll
	 */
	public boolean pollDailies()
	{
		Map<String, DailyTask> fresh = Dailies.read(client);
		MiscellaniaData kingdom = Dailies.readMiscellania(client, configManager);
		boolean changed = !Objects.equals(fresh, dailies) || !Objects.equals(kingdom, miscellania);
		dailies = fresh;
		miscellania = kingdom;
		return changed;
	}

	private Map<String, Integer> minigamePoints = null;

	/**
	 * Polls the minigame reward-shop currencies.
	 *
	 * @return whether any balance changed since the last poll
	 */
	public boolean pollMinigamePoints()
	{
		Map<String, Integer> fresh = MinigamePoints.read(client);
		boolean changed = !fresh.equals(minigamePoints);
		minigamePoints = fresh;
		return changed;
	}

	private Map<String, Integer> toolLeprechaun = null;

	/**
	 * Polls the varbit-backed skilling storages: the plank sack (kept under {@code storages.plankSack} once it
	 * has held planks) and the tool leprechaun.
	 *
	 * @return whether either changed since the last poll
	 */
	public boolean pollSkillingStorages()
	{
		List<ItemEntry> planks = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : SkillingStorage.PLANK_SACK.entrySet())
		{
			int amount = client.getVarbitValue(entry.getValue());
			if (amount > 0)
				planks.add(new ItemEntry(entry.getKey(), getItemName(entry.getKey()), amount));
		}

		boolean changed = false;
		List<ItemEntry> previous = storages.get(PLANK_SACK_KEY);
		if ((previous != null || !planks.isEmpty()) && !planks.equals(previous))
		{
			storages.put(PLANK_SACK_KEY, planks);
			storageUpdated.put(PLANK_SACK_KEY, Instant.now());
			changed = true;
		}

		Map<String, Integer> tools = SkillingStorage.readToolLeprechaun(client);
		changed |= !Objects.equals(tools, toolLeprechaun);
		toolLeprechaun = tools;
		return changed;
	}

	private TransportData transport = null;

	/**
	 * Polls the transport unlocks.
	 *
	 * @return whether they changed since the last poll
	 */
	public boolean pollTransport()
	{
		TransportData fresh = Transport.read(client);
		boolean changed = !fresh.equals(transport);
		transport = fresh;
		return changed;
	}

	private HouseData house = null;

	/**
	 * Polls the player-owned house fields.
	 *
	 * @return whether they changed since the last poll
	 */
	public boolean pollHouse()
	{
		HouseData fresh = House.read(client);
		boolean changed = !Objects.equals(fresh, house);
		house = fresh;
		return changed;
	}

	private SailingData sailing = null;

	/**
	 * Polls the Sailing state.
	 *
	 * @return whether it changed since the last poll
	 */
	public boolean pollSailing()
	{
		SailingData fresh = Sailing.read(client);
		boolean changed = !fresh.equals(sailing);
		sailing = fresh;
		return changed;
	}
}

