		old.storages = new LinkedHashMap<>();
		String[] keys = {"huntsmansKit", "forestryKit", "dizanasQuiver", "cargoHold1", "cargoHold5",
			"barbarianKnapsack"};
		for (String key : keys)
		{
			old.storages.put(key, Collections.singletonList(new ItemEntry(7, "Bones", 3)));
			old.sectionUpdated.put("storages." + key, OLD_BANK_TIME);
		}

		collector.restore(old);
		CharacterSnapshot data = collector.buildSnapshot();

		for (String key : keys)
		{
			assertEquals(Arrays.asList(7), ids(data.storages.get(key)));
			assertEquals(OLD_BANK_TIME, data.sectionUpdated.get("storages." + key));
		}
	}

	/**
	 * Obtained items (opacity 0) are captured per page, merged across pages, and persisted via restore.
	 */
	@Test
	public void collectionLogCapturesObtainedItemsPerPage()
	{
		Client client = loggedInClient("Zezima");
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT)).thenReturn(3);
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX)).thenReturn(1500);
		ItemComposition whip = named("Abyssal whip");
		when(client.getItemDefinition(11)).thenReturn(whip);
		SnapshotCollector collector = new SnapshotCollector(client, allEnabled());

		logPage(client, "Abyssal Sire", clogItem(11, 1, 0), clogItem(12, 0, 175));
		assertTrue(collector.captureCollectionLog());
		assertTrue(!collector.captureCollectionLog());
		logPage(client, "Barrows", clogItem(11, 2, 0), clogItem(13, 5, 0));
		assertTrue(collector.captureCollectionLog());

		CharacterSnapshot snap = collector.buildSnapshot();
		assertEquals(3, snap.collectionLog.obtained);
		assertEquals(1500, snap.collectionLog.total);
		assertEquals(2, snap.collectionLog.items.size());
		assertEquals("Abyssal whip", snap.collectionLog.items.get(0).name);
		assertEquals(2, snap.collectionLog.pages.get("Abyssal Sire").total);
		assertEquals(1, snap.collectionLog.pages.get("Abyssal Sire").obtained);
		assertNotNull(snap.sectionUpdated.get("collectionLog"));

		SnapshotCollector fresh = new SnapshotCollector(loggedInClient("Zezima"), allEnabled());
		CharacterSnapshot previous = previous("Zezima", "x");
		previous.collectionLog = snap.collectionLog;
		fresh.restore(previous);
		assertEquals(2, fresh.buildSnapshot().collectionLog.pages.size());
	}

	/**
	 * Nothing is captured when the log interface is not open, and no section is exported.
	 */
	@Test
	public void collectionLogNeedsOpenInterface()
	{
		Client client = loggedInClient("Zezima");
		SnapshotCollector collector = new SnapshotCollector(client, allEnabled());

		assertTrue(!collector.captureCollectionLog());
		assertNull(collector.buildSnapshot().collectionLog);
	}

	/**
	 * A Search pass merges one entry per script event, keeps page data intact, closes once per pass, and
	 * survives a restore.
	 */
	@Test
	public void collectionLogSearchPassMergesAllItems()
	{
		Client client = loggedInClient("Zezima");
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT)).thenReturn(50);
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX)).thenReturn(1717);
		ItemComposition whip = named("Abyssal whip");
		when(client.getItemDefinition(11)).thenReturn(whip);
		SnapshotCollector collector = new SnapshotCollector(client, allEnabled());

		logPage(client, "Abyssal Sire", clogItem(11, 1, 0), clogItem(12, 0, 175));
		collector.captureCollectionLog();

		for (int id = 11; id < 61; id++)
			collector.recordCollectionLogItem(new Object[] {SnapshotCollector.CLOG_ITEM_SCRIPT_ID, id, 2, 0, null});

		assertTrue(collector.finishCollectionLogSearch());
		assertTrue(!collector.finishCollectionLogSearch());

		CharacterSnapshot snap = collector.buildSnapshot();
		assertEquals(50, snap.collectionLog.items.size());
		assertEquals(50, snap.collectionLog.obtained);
		assertEquals("Abyssal whip", snap.collectionLog.items.get(0).name);
		assertEquals(2, snap.collectionLog.items.get(0).quantity);
		assertEquals(1, snap.collectionLog.pages.size());
		assertEquals(1, snap.collectionLog.pages.get("Abyssal Sire").obtained);

		SnapshotCollector fresh = new SnapshotCollector(loggedInClient("Zezima"), allEnabled());
		CharacterSnapshot previous = previous("Zezima", "x");
		previous.collectionLog = snap.collectionLog;
		fresh.restore(previous);
		assertEquals(50, fresh.buildSnapshot().collectionLog.items.size());
	}

	/**
	 * A Search pass alone exports the section, and a repeat pass with unchanged data reports no change.
	 */
	@Test
	public void collectionLogSearchPassAloneAndMalformedArgs()
	{
		Client client = loggedInClient("Zezima");
		SnapshotCollector collector = new SnapshotCollector(client, allEnabled());

		collector.recordCollectionLogItem(null);
		collector.recordCollectionLogItem(new Object[] {4100});
		collector.recordCollectionLogItem(new Object[] {4100, "x", 1});
		assertTrue(!collector.finishCollectionLogSearch());
		assertNull(collector.buildSnapshot().collectionLog);

		collector.recordCollectionLogItem(new Object[] {4100, 7, 1, 0, null});
		assertTrue(collector.finishCollectionLogSearch());
		assertEquals(1, collector.buildSnapshot().collectionLog.items.size());
		assertNotNull(collector.buildSnapshot().collectionLog.pages);

		collector.recordCollectionLogItem(new Object[] {4100, 7, 1, 0, null});
		assertTrue(!collector.finishCollectionLogSearch());
	}

	/**
	 * Stubs the open collection log interface with a page title and item widgets.
	 *
	 * @param client the mock client
	 * @param title  the page title
	 * @param items  the item widgets
	 */
	private static void logPage(Client client, String title, Widget... items)
	{
		Widget titleWidget = mock(Widget.class);
		when(titleWidget.getText()).thenReturn(title);
		Widget header = mock(Widget.class);
		when(header.getChildren()).thenReturn(new Widget[] {titleWidget});
		when(header.getChild(0)).thenReturn(titleWidget);
		Widget content = mock(Widget.class);
		when(content.getChildren()).thenReturn(items);
		when(client.getWidget(InterfaceID.Collection.HEADER_TEXT)).thenReturn(header);
		when(client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS)).thenReturn(content);
	}

	/**
	 * Builds a collection log item widget.
	 *
	 * @param id       the item id
	 * @param quantity the shown quantity
	 * @param opacity  0 when obtained, greater otherwise
	 * @return the mock widget
	 */
	private static Widget clogItem(int id, int quantity, int opacity)
	{
		Widget w = mock(Widget.class);
		when(w.getItemId()).thenReturn(id);
		when(w.getItemQuantity()).thenReturn(quantity);
		when(w.getOpacity()).thenReturn(opacity);
		return w;
	}

	/**
	 * Once the local player is gone (login screen), the snapshot still carries the identity from the last
	 * live build; after a reset there is nothing to write.
	 */
	@Test
	public void snapshotUsesCachedIdentityWhenPlayerIsGone()
	{
		Client client = loggedInClient("Zezima");
		SnapshotCollector collector = new SnapshotCollector(client, allEnabled());
		assertEquals("Zezima", collector.buildSnapshot().player.username);

		when(client.getLocalPlayer()).thenReturn(null);
		assertEquals("Zezima", collector.buildSnapshot().player.username);

		collector.reset();
		assertNull(collector.buildSnapshot());
	}

	/**
	 * Inside an instance the exported location is the template area's point, flagged as instanced.
	 */
	@Test
	@SuppressWarnings("deprecation")
	public void instancedLocationIsMappedToTemplate()
	{
		Client client = loggedInClient("Zezima");
		Player player = client.getLocalPlayer();
		LocalPoint local = mock(LocalPoint.class);
		when(player.getLocalLocation()).thenReturn(local);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(1, 2, 0));
		when(client.isInInstancedRegion()).thenReturn(true);
		SnapshotCollector collector = new SnapshotCollector(client, allEnabled());

		try (MockedStatic<WorldPoint> worldPoint = mockStatic(WorldPoint.class))
		{
			WorldPoint template = new WorldPoint(3000, 4000, 1);
			worldPoint.when(() -> WorldPoint.fromLocalInstance(client, local)).thenReturn(template);
			CharacterSnapshot.LocationData location = collector.buildSnapshot().location;

			assertEquals(3000, location.x);
			assertEquals(4000, location.y);
			assertEquals(1, location.plane);
			assertEquals((3000 >> 6) << 8 | (4000 >> 6), location.regionId);
			assertTrue(location.instanced);
		}
	}

	/**
	 * Movement polling reports a change only when the position or run energy differs from the last poll.
	 */
	@Test
	public void movementPollDetectsLocationAndEnergyChanges()
	{
		Client client = loggedInClient("Zezima");
		Player player = client.getLocalPlayer();
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
		when(client.getEnergy()).thenReturn(10000);
		SnapshotCollector collector = new SnapshotCollector(client, allEnabled());

		assertTrue(collector.pollMovement());
		assertFalse(collector.pollMovement());

		when(player.getWorldLocation()).thenReturn(new WorldPoint(3201, 3200, 0));
		assertTrue(collector.pollMovement());
		assertFalse(collector.pollMovement());

		when(client.getEnergy()).thenReturn(9900);
		assertTrue(collector.pollMovement());
		assertFalse(collector.pollMovement());

		when(client.getEnergy()).thenReturn(9910);
		assertFalse(collector.pollMovement());
	}

	/**
	 * With location and vitals export disabled, movement never marks the snapshot dirty.
	 */
	@Test
	public void movementPollIgnoresDisabledSections()
	{
		Client client = loggedInClient("Zezima");
		Player player = client.getLocalPlayer();
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
		CharacterSnapshotConfig config = allEnabled();
		when(config.syncLocation()).thenReturn(false);
		when(config.syncVitals()).thenReturn(false);
		SnapshotCollector collector = new SnapshotCollector(client, config);

		collector.pollMovement();
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3201, 3200, 0));
		when(client.getEnergy()).thenReturn(5000);

		assertFalse(collector.pollMovement());
	}
}

